{#- Right Image Quotation - 3-page solar proposal (Chrome PDF, A4, zero margins).
    Artwork is BUILT IN below (no upload needed). To override, upload a PUBLIC file with one of these names:
    RightImage-Quote-Page1-Background.jpg,
    RightImage-Quote-Page1-Middle-Image.jpg, RightImage-Quote-Page2-Background.jpg, RightImage-Quote-Page3-Background.jpg.
    The newest upload with a name wins, so re-uploading the middle image replaces the cover.
    (If the Company has the optional custom_qp_* Attach Image fields filled, those are used first.)
    Works on any site: custom fields that don't exist are simply skipped.
    Layout is authored on the original 1240 x 1635 px artwork grid, printed full-bleed on A4 (no white bands). -#}
{%- macro num(s) -%}
{%- set ns = namespace(n="", on=false, done=false) -%}
{%- for ch in (s or "")|string -%}{%- if not ns.done -%}
{%- if ch in "0123456789." -%}{%- set ns.n = ns.n ~ ch -%}{%- set ns.on = true -%}{%- elif ns.on -%}{%- set ns.done = true -%}{%- endif -%}
{%- endif -%}{%- endfor -%}{{ ns.n.strip(".") }}
{%- endmacro -%}
{%- macro num_before_kw(s) -%}
{%- set u = (s or "")|string|upper -%}{%- set i = u.find("KW") -%}
{%- if i > 0 -%}{%- set seg = u[:i]|trim -%}{%- set ns = namespace(n="") -%}
{%- for ch in seg|reverse -%}{%- if ns.n is not none -%}{%- if ch in "0123456789." -%}{%- set ns.n = ch ~ ns.n -%}{%- else -%}{%- set ns.n = none -%}{%- endif -%}{%- endif -%}{%- endfor -%}
{{- (ns.n if ns.n is not none else "")|string -}}
{%- endif -%}
{%- endmacro -%}
{%- macro nice(x) -%}{%- set f = x|float -%}{{ (f|int) if f == (f|int) else f }}{%- endmacro -%}
{%- macro url(p) -%}{%- if p -%}{{ p if p.startswith("http") else frappe.utils.get_url(p) }}{%- endif -%}{%- endmacro -%}

{#- ---------- data ---------- -#}
{%- macro art(company, field, fname) -%}
{%- set v = frappe.db.get_value("Company", company, field) if frappe.get_meta("Company").has_field(field) else none -%}
{%- if not v -%}{%- set f = frappe.get_all("File", filters={"file_name": fname, "is_private": 0}, fields=["file_url"], order_by="creation desc", limit_page_length=1) -%}{%- set v = f[0].file_url if f else "" -%}{%- endif -%}
{%- if v -%}{{ v if v.startswith("http") else frappe.utils.get_url(v) }}{%- endif -%}
{%- endmacro -%}
{%- set img1 = art(doc.company, "custom_qp_page1", "RightImage-Quote-Page1-Background.jpg") -%}
{%- set imgc = art(doc.company, "custom_qp_cover", "RightImage-Quote-Page1-Middle-Image.jpg") -%}
{%- set img2 = art(doc.company, "custom_qp_page2", "RightImage-Quote-Page2-Background.jpg") -%}
{%- set img3 = art(doc.company, "custom_qp_page3", "RightImage-Quote-Page3-Background.jpg") -%}
{#- Built-in artwork (used when no uploaded file / Company field overrides it) -#}
{%- if not img1 -%}{%- set img1 = "data:image/jpeg;base64," -%}{%- endif -%}
{%- if not imgc -%}{%- set imgc = "data:image/jpeg;base64," -%}{%- endif -%}
{%- if not img2 -%}{%- set img2 = "data:image/jpeg;base64," -%}{%- endif -%}
{%- if not img3 -%}{%- set img3 = "data:image/jpeg;base64," -%}{%- endif -%}
{%- set cap_s = num(doc.custom_total_capacity) -%}
{%- set cap = (cap_s|float) if cap_s else 0 -%}

{%- set it = namespace(panel=none, inverter=none) -%}
{%- for row in doc.items -%}
  {%- if row.item_group == "Panel" and not it.panel -%}{%- set it.panel = row -%}{%- endif -%}
  {%- if row.item_group == "Inverter" and not it.inverter -%}{%- set it.inverter = row -%}{%- endif -%}
{%- endfor -%}
{%- set inv_s = num_before_kw(it.inverter.item_name) if it.inverter else "" -%}
{%- set inv = (inv_s|float) if inv_s else cap -%}
{%- set inv_brand = ((it.inverter.custom_print_make or it.inverter.brand or (it.inverter.item_name or "").split(" ")[0]) if it.inverter else "") -%}

{%- set has_crm = frappe.db.exists("DocType", "CRM Lead") -%}
{%- set crm_lead = doc.party_name if doc.quotation_to == "CRM Lead" else ((frappe.db.get_value("Customer", doc.party_name, "custom_crm_lead") if frappe.get_meta("Customer").has_field("custom_crm_lead") else none) if doc.quotation_to == "Customer" else none) -%}
{%- set place = frappe.db.get_value("Address", doc.customer_address, "city") if doc.customer_address else none -%}
{%- if not place and crm_lead and has_crm and frappe.get_meta("CRM Lead").has_field("custom_location") -%}{%- set place = frappe.db.get_value("CRM Lead", crm_lead, "custom_location") -%}{%- endif -%}
{%- set salutation = frappe.db.get_value("Contact", doc.contact_person, "salutation") if doc.contact_person else none -%}
{%- if not salutation and crm_lead and has_crm -%}{%- set salutation = frappe.db.get_value("CRM Lead", crm_lead, "salutation") -%}{%- endif -%}
{%- set who = ((salutation ~ ". ") if salutation and not salutation.endswith(".") else ((salutation ~ " ") if salutation else "")) ~ (doc.customer_name or doc.party_name) ~ ((" - " ~ place) if place else "") -%}
{%- set bar_len = (who|length) + 14 -%}
{%- set bar_px = 64 if bar_len <= 43 else (64 * 43 / bar_len)|round(0, "floor")|int -%}

{%- set d = frappe.utils.getdate(doc.transaction_date) -%}
{%- set total = doc.rounded_total or doc.grand_total -%}
{%- set words = (doc.in_words or "")|replace("INR ", "")|replace("₹ ", "") -%}
{%- set words = words[:-1] if words.endswith(".") else words -%}

{%- if doc.custom_subsidy_amount -%}{%- set subsidy = doc.custom_subsidy_amount -%}
{%- elif cap <= 0 -%}{%- set subsidy = 0 -%}
{%- elif cap <= 2 -%}{%- set subsidy = 30000 * cap -%}
{%- elif cap <= 3 -%}{%- set subsidy = 60000 + 18000 * (cap - 2) -%}
{%- else -%}{%- set subsidy = 78000 -%}{%- endif -%}

{%- set particulars = doc.custom_price_particulars or (
    "Supply and Installation of " ~ nice(cap) ~ " KW Ongrid Solar Power Plant"
    ~ ((" with " ~ (it.panel.description|striptags|trim if it.panel.description else it.panel.item_name)) if it.panel else "")
    ~ ((", " ~ nice(inv) ~ " KW " ~ (inv_brand|title) ~ " Inverter") if it.inverter else "")
    ~ " and all accessories. (Including GST)") -%}

<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@62..125,700..900&family=Montserrat:wght@600;700&family=Open+Sans:wdth,wght@75..100,400..700&display=block" rel="stylesheet">
<style>
  @page { size: A4; margin: 0; }
  html, body { margin: 0 !important; padding: 0 !important; background: #fff; }
  .print-format { padding: 0 !important; margin: 0 !important; width: auto !important; max-width: none !important; min-height: 0 !important; box-shadow: none !important; }
  .ri-page { position: relative; width: 210mm; height: 296.9mm; overflow: hidden; background: #fff; page-break-after: always; break-after: page; }
  .ri-page:last-child { page-break-after: auto; break-after: auto; }
  /* Full-bleed A4: 1240px artwork grid -> 210mm wide; artwork stretched vertically x1.0726 to fill 297mm (text is not stretched) */
  .ri-stage { position: absolute; left: 0; top: 0; width: 1240px; height: 1754px; zoom: 0.640081; }
  .ri-bg { position: absolute; left: 0; top: 0; width: 1240px; height: 1754px; display: block; object-fit: fill; }
  .ri-abs { position: absolute; white-space: nowrap; }
  .ri-os { font-family: "Open Sans", Arial, sans-serif; }
  .ri-hd { font-family: "Archivo", "Arial Black", Arial, sans-serif; font-weight: 900; font-stretch: 86%; letter-spacing: -0.5px; }
  .ri-sp { font-family: "Montserrat", Arial, sans-serif; font-weight: 600; letter-spacing: 3px; text-transform: uppercase; color: #1b1b1b; }
  .ri-orange { color: #f4520a; }

  /* page 1 */
  .ri-year { left: 805px; top: 204px; font: 600 114px/120px "Open Sans", Arial, sans-serif; color: #fff; letter-spacing: -1px; }
  .ri-bar { left: 0; top: 361px; width: 1240px; height: 153px; display: flex; align-items: center; justify-content: center; font-family: "Open Sans", Arial, sans-serif; font-weight: 700; font-stretch: 82%; color: #fff; letter-spacing: 0; }
  .ri-bar b { color: #fbd01c; font-weight: 700; }
  .ri-cover { position: absolute; left: 0; top: 515px; width: 1240px; height: 860px; object-fit: fill; display: block; }
  .ri-ref { left: 830px; top: 1493px; font: 600 39px/64px "Open Sans", Arial, sans-serif; font-stretch: 78%; color: #141414; letter-spacing: -0.3px; }

  /* page 2 */
  .ri-t2a { left: 270px; top: 484px; font-size: 64px; line-height: 64px; font-stretch: 80%; letter-spacing: 0; }
  .ri-t2b { left: 270px; top: 547px; font-size: 25px; line-height: 32px; }
  .ri-tblwrap { position: absolute; left: 50px; top: 692px; width: 1145px; }
  .ri-tbl { width: 100%; border-collapse: separate; border-spacing: 0; table-layout: fixed; font-family: "Open Sans", Arial, sans-serif; font-size: 23px; line-height: 28px; color: #2a2a2a; }
  .ri-tbl th { background: #034079; color: #fff; font-weight: 700; font-size: 25px; height: 52px; padding: 0 22px; text-align: center; }
  .ri-tbl th:first-child { text-align: left; border-top-left-radius: 12px; }
  .ri-tbl th:last-child { border-top-right-radius: 12px; }
  .ri-tbl td { padding: 9px 22px; height: 44px; vertical-align: middle; border-right: 1.5px solid #b9cbe2; border-bottom: 1.5px solid #b9cbe2; background: #fff; overflow-wrap: normal; word-break: normal; hyphens: none; }
  .ri-tbl td:first-child { border-left: 1.5px solid #b9cbe2; }
  .ri-tbl tr:nth-child(even) td { background: #eef5fc; }
  .ri-tbl td.c { text-align: center; padding-left: 6px; padding-right: 6px; }
  .ri-tbl td.m { padding-left: 24px; padding-right: 8px; }
  .ri-tbl td.w { padding-left: 28px; padding-right: 10px; }
  .ri-tbl tr:last-child td:first-child { border-bottom-left-radius: 12px; }
  .ri-tbl tr:last-child td:last-child { border-bottom-right-radius: 12px; }

  /* page 3 */
  .ri-t3a { left: 318px; top: 386px; font-size: 60px; line-height: 64px; font-stretch: 78%; letter-spacing: 0; }
  .ri-t3a small { font-size: 42px; }
  .ri-part { left: 100px; top: 618px; width: 735px; height: 150px; display: flex; align-items: center; white-space: normal; font: 400 27px/38px "Open Sans", Arial, sans-serif; color: #2b2b2b; }
  .ri-price { left: 846px; top: 614px; width: 342px; height: 157px; display: flex; align-items: center; justify-content: center; font: 400 31px/1 "Open Sans", Arial, sans-serif; color: #222; }
  .ri-total { left: 846px; top: 770px; width: 342px; height: 85px; display: flex; align-items: center; justify-content: center; font: 700 38px/1 "Open Sans", Arial, sans-serif; color: #0d1b33; letter-spacing: -0.5px; }
  .ri-words { left: 233px; top: 944px; width: 945px; font: 500 31px/44px "Open Sans", Arial, sans-serif; color: #1e1e1e; overflow: hidden; text-overflow: ellipsis; }
  .ri-subsidy { left: 578px; top: 1358px; height: 112px; line-height: 112px; font-size: 94px; font-stretch: 84%; color: #0b2a63; letter-spacing: 0; }
</style>

{#- ================= PAGE 1 : cover ================= -#}
<div class="ri-page"><div class="ri-stage">
  {%- if img1 %}<img class="ri-bg" src="{{ img1 }}">{% endif %}
  {%- if imgc %}<img class="ri-cover" src="{{ imgc }}">{% endif %}
  <div class="ri-abs ri-year">{{ d.year }}</div>
  <div class="ri-abs ri-bar" style="font-size: {{ bar_px }}px;">Quotation for&nbsp;<b>{{ who }}</b></div>
  <div class="ri-abs ri-ref">Ref: {{ doc.name }}<br>Date:{{ d.strftime("%d.%m.%Y") }}</div>
</div></div>

{#- ================= PAGE 2 : products & specifications ================= -#}
<div class="ri-page"><div class="ri-stage">
  {%- if img2 %}<img class="ri-bg" src="{{ img2 }}">{% endif %}
  <div class="ri-abs ri-hd ri-orange ri-t2a">{{ nice(cap) }} KW SOLAR GRID TIE SYSTEM</div>
  <div class="ri-abs ri-sp ri-t2b">WITH {{ nice(inv) }} KW STRING INVERTER</div>
  <div class="ri-tblwrap">
    <table class="ri-tbl">
      <colgroup><col style="width:450px"><col style="width:152px"><col style="width:273px"><col style="width:270px"></colgroup>
      <thead><tr><th>Materials</th><th>Qty</th><th>Make</th><th>Warranty</th></tr></thead>
      <tbody>
      {%- for row in doc.items %}
        {%- set desc = (row.description|striptags|trim) if row.description else "" -%}
        <tr>
          <td>{{ desc or row.item_name }}</td>
          <td class="c">{{ row.custom_print_qty or nice(row.qty) }}</td>
          <td class="m">{{ (row.custom_print_make or row.brand or "")|upper }}</td>
          <td class="w">{{ (row.custom_warranty or "")|upper }}</td>
        </tr>
      {%- endfor %}
      {%- if cap %}
        <tr>
          <td>PRODUCTION</td>
          <td class="c">&ndash;</td>
          <td class="m"></td>
          <td class="w">{{ nice((cap * 4)|round(1)) }} UNITS PER DAY SUBJECT TO SUNLIGHT</td>
        </tr>
      {%- endif %}
      </tbody>
    </table>
  </div>
</div></div>

{#- ================= PAGE 3 : pricing ================= -#}
<div class="ri-page"><div class="ri-stage">
  {%- if img3 %}<img class="ri-bg" src="{{ img3 }}">{% endif %}
  <div class="ri-abs ri-hd ri-orange ri-t3a">{{ nice(cap) }} kW PANEL <small>WITH</small> {{ nice(inv) }} kW INVERTER</div>
  <div class="ri-abs ri-part">{{ particulars }}</div>
  <div class="ri-abs ri-price">{{ frappe.utils.fmt_money(total, 2, None, "#,##,###.##") }}</div>
  <div class="ri-abs ri-total">{{ frappe.utils.fmt_money(total, 0, None, "#,##,###.##") }}/-</div>
  <div class="ri-abs ri-words">({{ words }})</div>
  {%- if subsidy %}<div class="ri-abs ri-hd ri-subsidy">{{ subsidy|int }} /-</div>{% endif %}
</div></div>

{#-
  ================================================================
  SOLAR QUOTATION - 5-page A4 brochure print format (Right Image Energy)
  Doctype: Quotation  |  Engine: wkhtmltopdf  |  Custom Format: Yes
  ================================================================
  Everything transactional comes from the Quotation (doc) or the Company.
  Edit the static copy in the CONFIG block below - nothing else needs touching.

  Custom fieldnames used (all exist on this site):
    Quotation       custom_total_capacity, custom_roof_type, custom_solar_package
    Quotation Item  custom_solar_type, custom_item_capacity   (brand = Make)
-#}
{%- set cfg = {
  "tagline": "SOLAR ENERGY",
  "category": "FOR HOMES & BUSINESSES",
  "hero_lines": ["POWERING", "A BRIGHTER", "TOMORROW"],
  "hero_sub": "Sustainable Solar Solutions for Homes & Businesses",
  "features": [
    ["bolt", "Reduce Electricity Bills"],
    ["leaf", "Clean & Green Energy"],
    ["shield", "Reliable Quality Products"],
    ["tool", "Complete Installation & Support"]
  ],
  "cover_closing": "Let's build a cleaner and brighter future together!",
  "profile": "{company} is a trusted solar solutions provider committed to delivering clean, affordable and sustainable energy for homes and businesses. We specialise in rooftop solar systems, with end-to-end support from site survey and design to installation, net-metering and after-sales service.",
  "pillars": [
    ["target", "OUR VISION", "To make clean energy accessible to every home and business."],
    ["users", "OUR VALUES", "Integrity | Quality | Sustainability | Customer Satisfaction"],
    ["chart", "OUR MISSION", "Deliver reliable solar solutions with quality products and customer focus."],
    ["gear", "OUR EXPERTISE", "Residential | Commercial | Industrial | Rooftop Solar Systems"]
  ],
  "banner_lines": ["CLEAN ENERGY", "BRIGHTER", "TOMORROW"],
  "why_us": [
    ["shield", "Trusted Brands", "Tier-1 panels and inverters from reputed manufacturers."],
    ["tool", "Expert Installation", "Trained teams and safe, standards-compliant installation."],
    ["phone", "Dependable Support", "Prompt after-sales service and maintenance support."]
  ],
  "payment_terms": [
    ["Advance (On Order Confirmation)", "50%"],
    ["Before Installation", "40%"],
    ["After Commissioning", "10%"]
  ],
  "services": [
    "Site Survey & Design",
    "Supply of Materials",
    "Installation & Commissioning",
    "Net Metering Assistance",
    "After Sales Support",
    "Maintenance Support"
  ],
  "terms": [
    "Prices are valid for 30 days from the date of this quotation.",
    "Any additional work due to site conditions will be charged separately.",
    "Net metering approvals are subject to authority regulations.",
    "Warranty is as per manufacturer terms.",
    "Payment is to be made in the company bank account only."
  ],
  "closing_lines": ["Clean Energy", "Brighter Tomorrow"]
} -%}

{#- ---------------------------------------------------------------- data -#}
{%- set company = frappe.get_doc("Company", doc.company) -%}
{%- set cname = company.company_name or doc.company -%}
{%- set logo = company.company_logo -%}

{%- set addr = namespace(doc=None) -%}
{%- if doc.company_address -%}
  {%- set addr.doc = frappe.get_doc("Address", doc.company_address) -%}
{%- else -%}
  {%- set _links = frappe.get_all("Dynamic Link", filters={"link_doctype": "Company", "link_name": doc.company, "parenttype": "Address"}, fields=["parent"], limit=1) -%}
  {%- if _links -%}{%- set addr.doc = frappe.get_doc("Address", _links[0].parent) -%}{%- endif -%}
{%- endif -%}
{%- set a = addr.doc -%}
{%- set addr_line1 = ((a.address_line1 or "") ~ ((", " ~ a.address_line2) if a and a.address_line2 else "")) if a else "" -%}
{%- set addr_line2 = ([a.city, a.state, a.pincode] | select | join(", ")) if a else "" -%}
{%- set cphone = company.phone_no or (a.phone if a else "") -%}
{%- set cemail = company.email or (a.email_id if a else "") -%}
{%- set cweb = (company.website or "") | replace("https://", "") | replace("http://", "") -%}

{%- set cust_name = doc.customer_name or doc.party_name -%}
{%- set cust_mobile = doc.contact_mobile or doc.contact_phone -%}
{%- set capacity = doc.custom_total_capacity -%}
{%- set pkg = doc.custom_solar_package -%}
{%- set roof = doc.custom_roof_type -%}
{%- set nitems = (doc.items or []) | length -%}
{#- Page 3 must stay one page: rows tighten as the item count grows (tested up to 22 items with GST rows). -#}
{%- set density = "xxdense" if nitems > 16 else ("xdense" if nitems > 11 else ("dense" if nitems > 7 else "")) -%}

{%- set bank = namespace(row=None) -%}
{%- set _banks = frappe.get_all("Bank Account", filters={"company": doc.company, "is_company_account": 1}, fields=["bank", "account_name", "bank_account_no", "branch_code", "is_default"], order_by="is_default desc", limit=1) -%}
{%- if _banks -%}{%- set bank.row = _banks[0] -%}{%- endif -%}

{%- macro money(v) -%}{{ frappe.utils.fmt_money(v or 0, currency=doc.currency) }}{%- endmacro -%}
{%- macro fdate(d) -%}{{ frappe.utils.formatdate(d) if d else "" }}{%- endmacro -%}

{#- Line icons (feather-style), stroke = currentColor -#}
{%- macro icon(name, size=14, color="#1f7a4d", sw=2) -%}
<svg xmlns="http://www.w3.org/2000/svg" width="{{ size }}" height="{{ size }}" viewBox="0 0 24 24" fill="none" stroke="{{ color }}" stroke-width="{{ sw }}" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:middle">
{%- if name == "bolt" -%}<polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"/>
{%- elif name == "leaf" -%}<path d="M11 20A7 7 0 0 1 9.8 6.1C15.5 5 17 4.48 19 2c1 2 2 4.18 2 8 0 5.5-4.78 10-10 10Z"/><path d="M2 21c0-3 1.85-5.36 5.08-6C9.5 14.52 12 13 13 12"/>
{%- elif name == "shield" -%}<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/><polyline points="9 12 11 14 15 10"/>
{%- elif name == "tool" -%}<path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"/>
{%- elif name == "target" -%}<circle cx="12" cy="12" r="10"/><circle cx="12" cy="12" r="6"/><circle cx="12" cy="12" r="2"/>
{%- elif name == "users" -%}<path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>
{%- elif name == "chart" -%}<polyline points="23 6 13.5 15.5 8.5 10.5 1 18"/><polyline points="17 6 23 6 23 12"/>
{%- elif name == "gear" -%}<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 1 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06A1.65 1.65 0 0 0 4.6 15a1.65 1.65 0 0 0-1.51-1H3a2 2 0 1 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06A1.65 1.65 0 0 0 9 4.6a1.65 1.65 0 0 0 1-1.51V3a2 2 0 1 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06A1.65 1.65 0 0 0 19.4 9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 1 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/>
{%- elif name == "check" -%}<polyline points="20 6 9 17 4 12"/>
{%- elif name == "phone" -%}<path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45 12.84 12.84 0 0 0 2.81.7A2 2 0 0 1 22 16.92z"/>
