{#- Solar-panel artwork helpers: a quad (tl, tr, br, bl) split into a grid of PV panels. -#}
{%- macro vpt(ax, ay, bx, by, cx, cy, dx, dy, u, v) -%}
{%- set tx = ax + (bx - ax) * u -%}{%- set ty = ay + (by - ay) * u -%}
{%- set lx = dx + (cx - dx) * u -%}{%- set ly = dy + (cy - dy) * u -%}
{{- "%.1f,%.1f" | format(tx + (lx - tx) * v, ty + (ly - ty) * v) -}}
{%- endmacro -%}
{%- macro pvgrid(ax, ay, bx, by, cx, cy, dx, dy, cols, rows, gap, fill, lines) -%}
{%- for r in range(rows) -%}{%- for c in range(cols) -%}
{%- set u0 = c / cols + gap -%}{%- set u1 = (c + 1) / cols - gap -%}
{%- set v0 = r / rows + gap * 1.6 -%}{%- set v1 = (r + 1) / rows - gap * 1.6 -%}
<polygon points="{{ vpt(ax,ay,bx,by,cx,cy,dx,dy,u0,v0) }} {{ vpt(ax,ay,bx,by,cx,cy,dx,dy,u1,v0) }} {{ vpt(ax,ay,bx,by,cx,cy,dx,dy,u1,v1) }} {{ vpt(ax,ay,bx,by,cx,cy,dx,dy,u0,v1) }}" fill="{{ fill }}" stroke="#9fc3e0" stroke-width="0.8"/>
{%- if lines -%}
{%- set um = (u0 + u1) / 2 -%}{%- set vm = (v0 + v1) / 2 -%}
<polyline points="{{ vpt(ax,ay,bx,by,cx,cy,dx,dy,um,v0) }} {{ vpt(ax,ay,bx,by,cx,cy,dx,dy,um,v1) }}" fill="none" stroke="#5f8fb8" stroke-width="0.5" opacity="0.7"/>
<polyline points="{{ vpt(ax,ay,bx,by,cx,cy,dx,dy,u0,vm) }} {{ vpt(ax,ay,bx,by,cx,cy,dx,dy,u1,vm) }}" fill="none" stroke="#5f8fb8" stroke-width="0.5" opacity="0.7"/>
{%- endif -%}
{%- endfor -%}{%- endfor -%}
<polygon points="{{ vpt(ax,ay,bx,by,cx,cy,dx,dy,0.15,0) }} {{ vpt(ax,ay,bx,by,cx,cy,dx,dy,0.30,0) }} {{ vpt(ax,ay,bx,by,cx,cy,dx,dy,0.12,1) }} {{ vpt(ax,ay,bx,by,cx,cy,dx,dy,0.02,1) }}" fill="#ffffff" opacity="0.12"/>
{%- endmacro -%}

{#- Brand mark: company logo if set, otherwise a sun badge -#}
{%- macro brand(size_mm=12) -%}
{%- if logo -%}
<img src="{{ logo }}" style="max-height:{{ size_mm }}mm; max-width:{{ size_mm * 3 }}mm; display:block;">
{%- else -%}
<div class="rq-badge" style="width:{{ size_mm }}mm;height:{{ size_mm }}mm;">{{ icon("sun", (size_mm * 2.4) | int, "#ffffff", 2.2) }}</div>
{%- endif -%}
{%- endmacro -%}

