    <td style="vertical-align:bottom !important;">
      <div class="rq-eyebrow">COMMERCIAL OFFER</div>
      <div class="rq-title">QUOTATION</div>
      <div class="rq-rule"></div>
    </td>
    <td class="rq-qhead-r">
      <div class="rq-meta"><table>
        <tr><td class="k">Quotation No.</td><td class="v">{{ doc.name }}</td></tr>
        <tr><td class="k">Date</td><td class="v">{{ fdate(doc.transaction_date) }}</td></tr>
        <tr><td class="k">Valid Till</td><td class="v">{{ fdate(doc.valid_till) if doc.valid_till else "30 days from date" }}</td></tr>
      </table></div>
    </td>
  </tr></table>

  <table class="rq-party"><tr>
    <td>
      <div class="rq-party-box rq-soft">
        <div class="rq-party-lbl">{{ "CUSTOMER" if doc.quotation_to == "Customer" else "PREPARED FOR" }}</div>
        <div class="rq-party-name">{{ (cust_name or "") | e }}</div>
        {%- if doc.address_display -%}<div class="rq-party-addr">{{ doc.address_display }}</div>{%- endif -%}
        <div class="rq-party-contact">
          {%- if doc.contact_display and doc.contact_display != cust_name -%}{{ icon("users", 9) }}&nbsp; {{ doc.contact_display | e }}&nbsp;&nbsp;&nbsp;{%- endif -%}
          {%- if cust_mobile -%}{{ icon("phone", 9) }}&nbsp; {{ cust_mobile | e }}&nbsp;&nbsp;&nbsp;{%- endif -%}
          {%- if doc.contact_email -%}{{ icon("mail", 9) }}&nbsp; {{ doc.contact_email | e }}{%- endif -%}
        </div>
      </div>
    </td>
    {%- if pkg or capacity or roof -%}
    <td class="rq-party-gap"></td>
    <td class="rq-party-sys">
      <div class="rq-sys-box">
        <div class="rq-sys-lbl">{{ "SOLAR PACKAGE" if pkg else "SOLAR SYSTEM" }}</div>
        {%- if pkg -%}<div class="rq-sys-pkg">{{ pkg | e }}</div>{%- endif -%}
        <table class="rq-sys-kv" style="margin-top:1.4mm;">
          {%- if capacity -%}<tr><td>Total Capacity</td><td class="v">{{ capacity | e }}</td></tr>{%- endif -%}
          {%- if roof -%}<tr><td>Roof Type</td><td class="v">{{ roof | e }}</td></tr>{%- endif -%}
          <tr><td>Line Items</td><td class="v">{{ nitems }}</td></tr>
        </table>
      </div>
    </td>
    {%- endif -%}
  </tr></table>

  <div class="rq-intro">
    Dear {{ (cust_name or "Customer") | e }}, we are pleased to submit our quotation for the supply and installation of
    {%- if capacity %} a <b>{{ capacity | e }}</b>{% else %} a{% endif %} {% if roof %}{{ roof | e }} rooftop {% endif %}solar power system{% if pkg %} based on our <b>{{ pkg | e }}</b>{% endif %}, as detailed below.
  </div>

  <div class="rq-items {{ density }}">
    <table>
      <tr>
        <th class="ctr" style="width:7mm;">No.</th>
        <th style="width:21mm;">Item Code</th>
        <th>Particulars</th>
        <th class="num" style="width:16mm;">Qty</th>
        <th class="num" style="width:24mm;">Rate</th>
        <th class="num" style="width:20mm;">Discount</th>
        <th class="num" style="width:26mm;">Amount</th>
      </tr>
      {%- for row in doc.items -%}
      {%- set list_rate = row.price_list_rate if (row.price_list_rate or 0) > (row.rate or 0) else row.rate -%}
      {%- set line_disc = ((list_rate or 0) - (row.rate or 0)) * (row.qty or 0) -%}
      {%- set meta = [row.brand, row.custom_solar_type, row.custom_item_capacity] | select | join("  ·  ") -%}
      {%- set desc = frappe.utils.strip_html(row.description or "") | trim -%}
      <tr class="{{ 'alt' if loop.index % 2 == 0 else '' }}">
        <td class="ctr">{{ loop.index }}</td>
        <td class="rq-it-code">{{ row.item_code | e }}</td>
        <td>
          <div class="rq-it-name">{{ row.item_name | e }}</div>
          {%- if meta -%}<div class="rq-it-meta">{{ meta | e }}</div>{%- endif -%}
          {%- if desc and desc != row.item_name and desc != row.item_code -%}<div class="rq-it-desc">{{ desc | truncate(110) | e }}</div>{%- endif -%}
        </td>
        <td class="num">{{ "%g" | format(row.qty or 0) }} <span class="rq-muted" style="font-size:7pt;">{{ row.uom or "" }}</span></td>
        <td class="num">{{ money(list_rate) }}</td>
        <td class="num">{{ money(line_disc) if line_disc > 0.005 else "—" }}</td>
        <td class="num" style="font-weight:700;">{{ money(row.amount) }}</td>
      </tr>
