{%- endmacro -%}

{#- ================= PAGE 2 : products & specifications ================= -#}
{%- macro _page2() -%}
<div class="ri-stage">
  {%- if img2 %}<img class="ri-bg" src="{{ img2 }}">{% endif %}
  <div class="ri-abs ri-hd ri-orange ri-t2a">{{ nice(cap) }} KW SOLAR GRID TIE SYSTEM</div>
  <div class="ri-abs ri-sp ri-t2b">WITH {{ nice(inv) }} KW STRING INVERTER</div>
  <div class="ri-tblwrap">
    <table class="ri-tbl">
      <colgroup><col style="width:450px"><col style="width:152px"><col style="width:273px"><col style="width:270px"></colgroup>
      <thead><tr><th>Materials</th><th>Qty</th><th>Make</th><th>Warranty</th></tr></thead>
      <tbody>
      {%- for row in doc.items %}
        {%- set desc = (row.description|striptags|trim) if row.description else "" -%}
        <tr>
          <td>{{ desc or row.item_name }}</td>
          <td class="c">{{ row.custom_print_qty or nice(row.qty) }}</td>
          <td class="m">{{ (row.custom_print_make or row.brand or "")|upper }}</td>
          <td class="w">{{ (row.custom_warranty or "")|upper }}</td>
        </tr>
      {%- endfor %}
      {%- if cap %}
        <tr>
          <td>PRODUCTION</td>
          <td class="c">&ndash;</td>
          <td class="m"></td>
          <td class="w">{{ nice((cap * 4)|round(1)) }} UNITS PER DAY SUBJECT TO SUNLIGHT</td>
        </tr>
      {%- endif %}
      </tbody>
    </table>
  </div>
</div>
{%- endmacro -%}

{#- ================= PAGE 3 : pricing ================= -#}
{%- macro _page3() -%}
<div class="ri-stage">
  {%- if img3 %}<img class="ri-bg" src="{{ img3 }}">{% endif %}
  <div class="ri-abs ri-hd ri-orange ri-t3a">{{ nice(cap) }} kW PANEL <small>WITH</small> {{ nice(inv) }} kW INVERTER</div>
  <div class="ri-abs ri-part">{{ particulars }}</div>
  <div class="ri-abs ri-price">{{ frappe.utils.fmt_money(total, 2, None, "#,##,###.##") }}</div>
  <div class="ri-abs ri-total">{{ frappe.utils.fmt_money(total, 0, None, "#,##,###.##") }}/-</div>
  <div class="ri-abs ri-words">({{ words }})</div>
  {%- if subsidy %}<div class="ri-abs ri-hd ri-subsidy">{{ subsidy|int }} /-</div>{% endif %}
</div>
{%- endmacro -%}

{#- ================= PAGE ORDER + EXTRA PAGES =================
    Extra pages: defaults on this Print Format's Extra Pages table, replaced or skipped per quotation.
    Each prints at its page number; the format's own pages take the free numbers in order. -#}
{%- set _xm = {} -%}
{%- for p in _pf.get("custom_extra_pages") or [] -%}{%- if p.page_no -%}{%- set _ = _xm.update({p.page_no|int: p.image or ""}) -%}{%- endif -%}{%- endfor -%}
{%- for p in doc.get("custom_print_extra_pages") or [] -%}{%- if p.print_format == _pf.name and p.page_no -%}{%- set _ = _xm.update({p.page_no|int: p.image or ""}) -%}{%- endif -%}{%- endfor -%}
{%- set _xl = [] -%}
{%- for k in _xm.keys()|sort -%}{%- if _xm[k] -%}{%- set _ = _xl.append([k, _xm[k]]) -%}{%- endif -%}{%- endfor -%}
{%- set _xn = namespace(b=0, x=0, pos=1) -%}
{%- for _i in range(3 + _xl|length) -%}
<div class="ri-page{{ ' ri-brk' if not loop.first else '' }}">
{%- if _xn.x < _xl|length and (_xl[_xn.x][0] <= _xn.pos or _xn.b >= 3) -%}
<img class="ri-xp" src="{{ url(_xl[_xn.x][1]) }}">
{%- set _xn.x = _xn.x + 1 -%}
{%- else -%}
{%- if _xn.b == 0 -%}{{ _page1() }}{%- elif _xn.b == 1 -%}{{ _page2() }}{%- else -%}{{ _page3() }}{%- endif -%}
{%- set _xn.b = _xn.b + 1 -%}
{%- endif -%}
</div>
{%- set _xn.pos = _xn.pos + 1 -%}
{%- endfor -%}
